SELECT 

FROM bidding_management
WHERE 1=1

    AND bidding_no LIKE CONCAT('%', #{param.biddingNo}, '%')


    AND project_name LIKE CONCAT('%', #{param.projectName}, '%')


    AND project_type = #{param.projectType}


    AND project_id = #{param.projectId}


    AND owner_name LIKE CONCAT('%', #{param.ownerName}, '%')


    AND project_status = #{param.projectStatus}


    AND bidding_method = #{param.biddingMethod}


    AND manager_id = #{param.managerId}


    AND manager_name LIKE CONCAT('%', #{param.managerName}, '%')


    AND budget_amount >= #{param.minBudgetAmount}


    AND budget_amount <= #{param.maxBudgetAmount}


    AND bid_opening_date >= #{param.bidOpeningStartDate}


    AND bid_opening_date <= #{param.bidOpeningEndDate}


    AND bid_deadline >= #{param.bidDeadlineStartDate}


    AND bid_deadline <= #{param.bidDeadlineEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (project_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR project_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR tenderer_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR project_description LIKE CONCAT('%', #{param.keyword}, '%')
         OR manager_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COUNT(1) > 0
FROM bidding_management
WHERE bidding_no = #{biddingNo}

    AND id != #{excludeId}

SELECT COUNT(*)
FROM bidding_management
WHERE project_status = #{projectStatus}

SELECT COUNT(*)
FROM bidding_management
WHERE bidding_method = #{biddingMethod}

